W = 5
I, R = "Inkoop", "Recht"

# ---------- Inkoop MC (contractmanagement) ----------
mc("ir5-i01", W, I, "Hoe definiëren de slides contractmanagement?",
   ["Het opstellen en ondertekenen van contracten", "Het geheel van activiteiten gericht op het wederzijds nakomen van afspraken tussen leverancier en opdrachtgever, zodat maximale waarde ontstaat voor het bestede geld", "Het archiveren van contracten", "Het onderhandelen over de prijs bij verlenging"], 1,
   "Contractmanagement bewaakt of de organisatie krijgt wat is afgesproken en verbetert de prestaties van de leverancier. Het bestaat uit contractbeheer en prestatiemanagement.")
mc("ir5-i02", W, I, "Wat valt onder contractbeheer?",
   ["Het meten van KPI's en het bijsturen van de leverancier", "Het administratieve proces van registreren, beheren en archiveren van contracten en het verwerken van mutaties", "Het selecteren van nieuwe leveranciers", "Het bouwen van langetermijnrelaties"], 1,
   "Contractbeheer is administratief: wat staat er in de contracten, welke verplichtingen zijn er, wanneer lopen ze af of moeten ze verlengd worden. Prestatiemanagement gaat over meten en sturen.")
mc("ir5-i03", W, I, "Medewerkers bestellen kantoorartikelen bij een webwinkel terwijl er een raamcontract met een vaste leverancier is. Hoe heet dit?",
   ["Single sourcing", "Maverick buying", "Contractbeheer", "Co-makership"], 1,
   "Maverick buying is inkopen buiten de contracten om. Goed contractbeheer (inzicht in welke contracten er zijn) helpt dit te voorkomen.")
mc("ir5-i04", W, I, "Een contract voor de koffieautomaten wordt stilzwijgend met drie jaar verlengd, omdat niemand de opzegtermijn in de gaten had. Welke pijler van contractmanagement schiet tekort?",
   ["Relatiemanagement", "Contractadministratie", "Leveranciersontwikkeling", "Duurzaamheid"], 1,
   "Contractadministratie (pijler 2) zorgt voor inzicht in verplichtingen, deadlines en mijlpalen, bij voorkeur met een geautomatiseerd systeem dat waarschuwt bij expiratiedata.")
mc("ir5-i05", W, I, "Wat hoort bij pijler 1, governance?",
   ["Beleid en procedures, rollen en verantwoordelijkheden, toezicht en verantwoording, risicobeheersing en compliance", "KPI's en SLA's meten", "Stakeholdermanagement en conflictoplossing", "Het leveranciersbestand rationaliseren"], 0,
   "Governance is het raamwerk: wie doet wat, welk beleid geldt, hoe wordt verantwoording afgelegd. Best practice: een centraal contractmanagementbeleid en een bepaalde ambitie.")
mc("ir5-i06", W, I, "Wat betekent 'balans in sturing: hard op inhoud, zacht op relatie' bij prestatiemanagement?",
   ["Altijd boetes opleggen", "Strikt sturen op de afgesproken prestaties en KPI's, en tegelijk de samenwerking met de leverancier goed houden", "Alleen sturen op de relatie", "De leverancier zelf zijn KPI's laten kiezen"], 1,
   "Prestatiemanagement (pijler 3) meet en stuurt met KPI's en SLA's en lost issues op, maar wel zo dat de samenwerking verbetert in plaats van verslechtert.")
mc("ir5-i07", W, I, "Bij welke pijler staat de contractmanager 'in het centrum van het web van relaties'?",
   ["Governance", "Contractadministratie", "Relatiemanagement", "Prestatiemanagement"], 2,
   "Relatiemanagement (pijler 4): stakeholdermanagement intern en extern, consistente communicatie en constructieve conflictoplossing.")
mc("ir5-i08", W, I, "Een facilitair manager werkt met een strategische cateraar aan gezamenlijke doelen en innovatie, binnen de grenzen van de aanbestedingsregels. Welke pijler is dit?",
   ["Contractadministratie", "Leveranciersmanagement en -ontwikkeling", "Governance", "Contractbeheer"], 1,
   "Pijler 5 gaat over het verkennen, onderhouden en ontwikkelen van relaties met leveranciers, met focus op leveranciers met een hoge waardekans. Bij publieke organisaties binnen de kaders van Europees aanbesteden.")
mc("ir5-i09", W, I, "Lidl richt zijn inkoopbeleid op kostenleiderschap, ASML op innovatie. Wat betekent dat voor contractmanagement?",
   ["Niets, contractmanagement is overal hetzelfde", "De ambitie en focus van contractmanagement volgen uit het inkoop- en organisatiebeleid: bij Lidl sturen op prijs en efficiëntie, bij ASML op samenwerking en innovatie", "Bij ASML is contractmanagement niet nodig", "Lidl moet altijd single sourcing toepassen"], 1,
   "Contractmanagement sluit aan op de inkoopstrategie, die weer volgt uit het organisatiebeleid. Bij kostenleiderschap stuur je hard op prijs en efficiëntie, bij innovatie op samenwerking en ontwikkeling.")
mc("ir5-i10", W, I, "Wat noemen de slides als strategisch voordeel van contractmanagement?",
   ["Meer leveranciers", "Grip op uitgaven, risicobeheersing, waardecreatie, afstemming op klantverwachtingen en duurzaamheid bevorderen", "Kortere aanbestedingen", "Minder wettelijke regels"], 1,
   "De slides noemen deze vijf strategische voordelen voor de bedrijfsvoering.")
mc("ir5-i11", W, I, "Je bent net contractmanager in een ziekenhuis waar nog geen contractmanagement is. Wat doe je het eerst?",
   ["Meteen alle leveranciers boetes geven", "Inzicht krijgen: welke contracten er zijn, wie de eigenaren zijn en wat de belangrijkste risico's en deadlines zijn", "Alle contracten opzeggen", "Een nieuwe aanbesteding starten"], 1,
   "Zonder overzicht kun je niet sturen. Je begint met een inventarisatie (contractadministratie) en het gesprek met stakeholders, en legt daarna de governance vast.")
mc("ir5-i12", W, I, "Welke best practice hoort bij contractadministratie?",
   ["Diversifieer het leveranciersbestand", "Leg in de governance vast hoe met wijzigingen wordt omgegaan en wie daartoe bevoegd is, en houd contractgegevens actueel", "Bouw aan langetermijnrelaties", "Gebruik feedback van stakeholders"], 1,
   "Bij pijler 2 horen een geautomatiseerd systeem, actuele contractgegevens, bewaking van cruciale deadlines en vastgelegde regels voor wijzigingen en bevoegdheden.")

# ---------- Recht MC ----------
mc("ir5-r01", W, R, "Wat is het uitgangspunt bij afgebroken onderhandelingen?",
   ["Afbreken is altijd onrechtmatig", "Contractvrijheid: afbreken mag, tenzij dat door gerechtvaardigd vertrouwen of andere omstandigheden onaanvaardbaar is", "Afbreken mag alleen met toestemming van de rechter", "Na drie gesprekken is er altijd een overeenkomst"], 1,
   "Volgens de lijn Plas/Valburg, VSH/Shell en CBB/JPO is afbreken in beginsel vrij. Alleen als dat onaanvaardbaar is (vgl. art. 6:248 lid 2 BW) volgt aansprakelijkheid, en dat is niet snel het geval.")
mc("ir5-r02", W, R, "Welke omstandigheid weegt de rechter mee bij afgebroken onderhandelingen?",
   ["De nationaliteit van de partijen", "De mate waarin de afbrekende partij heeft bijgedragen aan het vertrouwen", "De omzet van de afbrekende partij", "Of de partijen elkaar al kenden"], 1,
   "Relevant zijn onder meer: de bijdrage van de afbreker aan het vertrouwen, de verwijtbaarheid, de belangen van partijen, gewijzigde of onvoorziene omstandigheden en de duur, steeds afgezet tegen het hele verloop van de onderhandelingen.")
mc("ir5-r03", W, R, "Waarom nemen partijen in een letter of intent een voorbehoud op, zoals 'pas gebonden na schriftelijke vastlegging en goedkeuring door het bestuur'?",
   ["Om de onderhandelingen te versnellen", "Om een rompovereenkomst en gerechtvaardigd totstandkomingsvertrouwen te voorkomen", "Omdat de wet dat verplicht", "Om de prijs vast te leggen"], 1,
   "Volgens oefenopdracht 5.1 voorkomen voorbehouden dat er al een (romp)overeenkomst ontstaat en dat de andere partij gerechtvaardigd mag vertrouwen op een contract. Je moet je er dan wel zelf ook aan houden.")
mc("ir5-r04", W, R, "Wat kan een partij vorderen bij onrechtmatig afgebroken onderhandelingen, als standaard uitgangspunt?",
   ["Altijd de gederfde winst (positief contractsbelang)", "De gemaakte kosten (negatief contractsbelang); gederfde winst alleen bij uitzondering", "Alleen dooronderhandelen", "Niets, want er is geen overeenkomst"], 1,
   "Het negatief contractsbelang (gemaakte kosten) is het standaard uitgangspunt. Het positief contractsbelang (gederfde winst) is een uitzondering, bijvoorbeeld bij schuld of opzet of een vergevorderd stadium.")
mc("ir5-r05", W, R, "Waarom wint een vordering tot dooronderhandelen vaak niet als de afbreker al een contract met een ander heeft gesloten?",
   ["Omdat de rechter niet bevoegd is", "Omdat toewijzing de afbreker zou dwingen tot wanprestatie tegenover die ander; daarom moet je snel handelen, eventueel in kort geding", "Omdat dooronderhandelen nooit kan", "Omdat de schadevergoeding dan al is betaald"], 1,
   "Er is geen contractsdwang. Heeft de afbreker al met een ander gecontracteerd, dan zou de rechter hem tot wanprestatie dwingen. Wie wil dooronderhandelen, moet daarom snel naar de kortgedingrechter.")
mc("ir5-r06", W, R, "Wat zijn volgens art. 6:231 BW GEEN algemene voorwaarden?",
   ["Schriftelijke bedingen voor meerdere overeenkomsten", "Bedingen die de kern van de prestaties aangeven, zoals prijs en product", "Een eigendomsvoorbehoud in de leveringsvoorwaarden", "Een exoneratiebeding in de verkoopvoorwaarden"], 1,
   "Kernbedingen (wat lever je, wat kost het) vallen buiten de definitie. Daar onderhandel je over, dus de bescherming van de AV-regeling is daar niet nodig.")
mc("ir5-r07", W, R, "Een klant heeft de algemene voorwaarden nooit gelezen. Is hij eraan gebonden?",
   ["Nee, alleen als hij ze gelezen heeft", "Ja, ook als hij de inhoud niet kende, als de gebruiker ze vóór of bij het sluiten van de overeenkomst van toepassing heeft verklaard (art. 6:232 BW)", "Alleen als hij ze ondertekend heeft", "Alleen als ze bij de KvK liggen"], 1,
   "Art. 6:232 BW zorgt voor snelle binding. Daar staan de vernietigingsgronden van art. 6:233 BW tegenover.")
mc("ir5-r08", W, R, "Welke onderneming kan GEEN beroep doen op de vernietigingsgronden van art. 6:233 BW?",
   ["Een bakker met 4 medewerkers", "Een bedrijf met 120 werknemers", "Een zzp'er", "Een consument"], 1,
   "Art. 6:235 BW sluit ondernemingen met 50 of meer werkzame personen uit, net als ondernemingen die laatstelijk hun jaarrekening openbaar hebben gemaakt. Zij hebben alleen art. 6:248 lid 2 BW.")
mc("ir5-r09", W, R, "Wat is het verschil tussen de zwarte en de grijze lijst?",
   ["Er is geen verschil", "Bedingen op de zwarte lijst (6:236) zijn altijd onredelijk bezwarend; bedingen op de grijze lijst (6:237) worden vermoed onredelijk bezwarend te zijn, met tegenbewijs voor de gebruiker", "De zwarte lijst geldt voor bedrijven, de grijze voor consumenten", "De grijze lijst is strenger dan de zwarte"], 1,
   "Beide lijsten gelden voor consumenten. Via reflexwerking kunnen ze ook betekenis hebben voor kleine ondernemers die met een consument te vergelijken zijn.")
mc("ir5-r10", W, R, "Starters verwijst als eerste naar haar eigen inkoopvoorwaarden. Punidas antwoordt met een offerte die naar haar eigen verkoopvoorwaarden verwijst. Welke voorwaarden gelden?",
   ["Die van Punidas, want die verwees als laatste", "Die van Starters (first-shot rule, art. 6:225 lid 3 BW), tenzij Punidas die uitdrukkelijk van de hand heeft gewezen", "Geen van beide", "Die van de grootste onderneming"], 1,
   "De eerste verwijzing geldt. Alleen verwijzen naar de eigen voorwaarden of afwijzen via een clausule in de eigen voorwaarden is niet genoeg: je moet de voorwaarden van de ander uitdrukkelijk van de hand wijzen.")
mc("ir5-r11", W, R, "Een leverancier verwijst naar voorwaarden 'die ter inzage liggen bij de griffie van de rechtbank', terwijl hij ze gewoon had kunnen meesturen. Gevolg voor een kleine afnemer?",
   ["Geen, verwijzen is altijd genoeg", "De voorwaarden zijn vernietigbaar (art. 6:233 sub b jo. 6:234 BW), want ter hand stellen was redelijkerwijs mogelijk", "De voorwaarden zijn nietig", "De afnemer moet ze zelf ophalen"], 1,
   "Ter inzage leggen bij de KvK of de griffie mag alleen als ter hand stellen redelijkerwijs niet mogelijk is. Dat hoort bij oefenopdracht 5.6.")
mc("ir5-r12", W, R, "Twee Nederlandse bedrijven verklaren in de algemene voorwaarden Duits recht van toepassing. Kan de wederpartij zich toch op art. 6:233 BW beroepen?",
   ["Nee, Duits recht geldt", "Ja, art. 6:247 lid 1 BW: tussen twee in Nederland gevestigde partijen is de Nederlandse AV-regeling dwingend van toepassing", "Alleen als de rechter Duits spreekt", "Alleen bij consumenten"], 1,
   "Art. 6:247 lid 1 BW maakt de Nederlandse regeling dwingend van toepassing als beide zakelijke partijen in Nederland gevestigd zijn (oefenopdracht 5.7). Lid 2 geldt als een van beide in het buitenland zit.")

# ---------- Open vragen ----------
op("ir5-io1", W, I, "Leg het verschil uit tussen contractbeheer en prestatiemanagement, en geef bij een schoonmaakcontract van elk twee concrete activiteiten.",
   "Contractbeheer is het administratieve deel: contracten registreren, beheren en archiveren en mutaties verwerken, zodat de organisatie weet wat er is afgesproken en wanneer contracten verlopen. Voorbeelden: het contract en de looptijd vastleggen in een contractbeheersysteem, en tijdig signaleren dat de opzegtermijn nadert. Prestatiemanagement gaat over het meten en sturen van de prestaties. Voorbeelden: maandelijkse kwaliteitsmetingen (bijvoorbeeld VSR) bespreken met de leverancier, en bij afwijkingen een verbeterplan of malus afspreken.",
   ["Contractbeheer juist uitgelegd", "Prestatiemanagement juist uitgelegd", "Twee passende activiteiten per onderdeel"])
op("ir5-io2", W, I, "Noem de vijf pijlers van contractmanagement volgens NEVI en geef bij elke pijler één best practice.",
   "1. Governance: een centraal contractmanagementbeleid en duidelijke rollen. 2. Contractadministratie: een geautomatiseerd contractmanagementsysteem met deadlines. 3. Prestatiemanagement: meetbare KPI's en SLA's en periodieke evaluaties. 4. Relatiemanagement: regelmatig overleg met interne en externe stakeholders en feedback gebruiken. 5. Leveranciersmanagement en -ontwikkeling: samen met strategische leveranciers werken aan gezamenlijke doelen en innovatie.",
   ["Vijf pijlers juist genoemd", "Bij elke pijler een passende best practice"])
op("ir5-io3", W, I, "Waarom is goed contractbeheer volgens de slides cruciaal? Noem vier redenen.",
   "Om te voorkomen dat er betaald wordt voor iets dat niet geleverd is, om de oorspronkelijke inkoopdoelstellingen echt te bereiken, om de bijbehorende risico's te beheersen, om kansen te benutten en door te ontwikkelen, en om maverick buying te voorkomen.",
   ["Vier juiste redenen"])
op("ir5-ro1", W, R, "Leg uit welke omstandigheden de rechter weegt bij de vraag of onderhandelingen onrechtmatig zijn afgebroken, en welke twee vorderingen de benadeelde partij heeft.",
   "Omstandigheden: de mate waarin de afbreker aan het vertrouwen heeft bijgedragen, zijn verwijtbaarheid, de belangen van partijen, gewijzigde of onvoorziene omstandigheden en de duur van de onderhandelingen, afgezet tegen het hele verloop. Uitgangspunt is contractvrijheid; aansprakelijkheid alleen als afbreken onaanvaardbaar is. Vorderingen: (1) dooronderhandelen, al is er geen contractsdwang en moet je snel zijn (kort geding); (2) schadevergoeding op grond van onrechtmatige daad (art. 6:162 BW): standaard het negatief contractsbelang (gemaakte kosten), bij uitzondering ook het positief contractsbelang (gederfde winst).",
   ["Minstens drie relevante omstandigheden", "Uitgangspunt contractvrijheid / onaanvaardbaarheid", "Vordering dooronderhandelen met kanttekening", "Schadevergoeding: negatief standaard, positief uitzondering"])
op("ir5-ro2", W, R, "Maak het overzicht van de vier typen wederpartijen bij algemene voorwaarden en geef per type aan op welke bescherming ze een beroep kunnen doen.",
   "1. Onderneming met 50 of meer werkzame personen (of die haar jaarrekening openbaar maakt, art. 6:235 BW): geen beroep op art. 6:233 en 6:234, en niet op de lijsten; alleen art. 6:248 lid 2 BW. 2. Onderneming met minder dan 50 werknemers: art. 6:233 sub a en b en 6:234 BW, geen lijsten. 3. Kleine onderneming die vergelijkbaar is met een consument: art. 6:233 en 6:234, en de lijsten via reflexwerking. 4. Consument: art. 6:233 en 6:234 plus de zwarte en de grijze lijst (art. 6:236 en 6:237 BW). Iedereen kan zich altijd op art. 6:248 lid 2 BW beroepen.",
   ["Vier typen juist onderscheiden", "Grote onderneming: alleen 6:248 lid 2", "Kleine onderneming: 6:233/6:234", "Consument: plus zwarte en grijze lijst (en reflexwerking)"])
op("ir5-ro3", W, R, "Wat is een exoneratieclausule, wanneer is die onaanvaardbaar, en waarom helpt art. 6:233 BW niet als de clausule in de overeenkomst zelf staat?",
   "Een exoneratieclausule beperkt of sluit de eigen aansprakelijkheid uit, bijvoorbeeld tot de factuurwaarde of het verzekerde bedrag. De rechter kan haar onaanvaardbaar achten op grond van art. 6:248 lid 2 BW. Gezichtspunten zijn onder meer risico, schuld of opzet, grote tegenover kleine onderneming, verzekerbaarheid en de aard van de schade (zaakschade tegenover letsel). De vernietigingsgronden van art. 6:233 BW gelden alleen voor bedingen in algemene voorwaarden. Staat de clausule in de individuele overeenkomst zelf, waarover is onderhandeld, dan biedt die regeling geen bescherming.",
   ["Definitie exoneratieclausule", "Toets via 6:248 lid 2 met minstens twee gezichtspunten", "6:233 geldt alleen voor bedingen in AV"])

# ---------- Casussen ----------
cs("ir5-ic1", W, I, "Contractmanagement opzetten bij een universiteit",
   "Je begint als eerste contractmanager bij een universiteit met 6.000 medewerkers. Er zijn ongeveer 400 contracten, verspreid over faculteiten en diensten, deels in mappen, deels in mailboxen. Vorig jaar werd het schoonmaakcontract stilzwijgend verlengd tegen een hogere prijs. Faculteiten kopen geregeld zelf meubilair in bij een webwinkel. De cateraar levert volgens de studenten 'wisselende kwaliteit', maar er zijn geen metingen.",
   [("Welke problemen zie je? Koppel elk probleem aan een pijler van contractmanagement.",
     "Geen centraal overzicht van contracten en gemiste opzegtermijnen: contractadministratie (pijler 2). Faculteiten die zelf meubilair kopen (maverick buying): governance (pijler 1), want rollen, beleid en bevoegdheden ontbreken, en ook contractbeheer. Geen metingen bij de cateraar: prestatiemanagement (pijler 3), zonder KPI's en SLA's. Klachten zonder structureel overleg: relatiemanagement (pijler 4).",
     ["Minstens drie problemen benoemd", "Elk probleem aan de juiste pijler gekoppeld"]),
    ("Maak een stappenplan voor je eerste drie maanden: waar begin je, wie spreek je, en hoe meet je voortgang?",
     "Maand 1: alle contracten inventariseren en vastleggen in één systeem met eigenaar, looptijd en opzegtermijn; stakeholders spreken (faculteitsdirecteuren, inkoop, financiën, de grootste leveranciers). Maand 2: governance vastleggen (beleid, rollen, wie mag tekenen en wijzigen) en prioriteren op risico en waarde. Maand 3: voor de grootste contracten (schoonmaak, catering) KPI's en evaluatiemomenten afspreken. Voortgang: het percentage contracten in het systeem, het aantal gemiste deadlines (doel 0), het aandeel uitgaven binnen contract, en de resultaten van de eerste KPI-metingen. Verantwoording aan de directeur bedrijfsvoering.",
     ["Logische volgorde: eerst inzicht/inventarisatie", "Relevante stakeholders genoemd", "Concrete voortgangsmaatstaven", "Aan wie verantwoording wordt afgelegd"]),
    ("Hoe pak je de 'wisselende kwaliteit' van de cateraar aan zonder de relatie te beschadigen?",
     "Hard op inhoud, zacht op relatie: samen met de cateraar meetbare KPI's en normen afspreken (bijvoorbeeld tevredenheidsscores en het assortiment volgens afspraak), periodiek evalueren en resultaten vastleggen. Bij afwijkingen een gezamenlijk verbeterplan maken in plaats van meteen een boete. Ook kijken naar de eigen organisatie, zoals onduidelijke wensen of wijzigingen.",
     ["Meetbaar maken met KPI's/SLA", "Balans hard op inhoud, zacht op relatie", "Aandacht voor eigen rol of gezamenlijke verbetering"])])
cs("ir5-rc1", W, R, "Afgebroken onderhandelingen over een nieuw kantoorconcept",
   "Facilitair bedrijf FaciPro onderhandelt al vier maanden met projectontwikkelaar BouwBest over de herinrichting van een kantoor. Er is een letter of intent getekend zonder voorbehouden. BouwBest liet FaciPro op eigen kosten een architect inschakelen (€18.000) en zei in de laatste bespreking: 'Wat ons betreft is het rond, de handtekening is een formaliteit.' Twee dagen later breekt BouwBest af, omdat een concurrent van FaciPro 5% goedkoper is. FaciPro had met deze opdracht een winst van €60.000 verwacht.",
   [("Mocht BouwBest de onderhandelingen afbreken? Bespreek het uitgangspunt en de relevante omstandigheden.",
     "Uitgangspunt is contractvrijheid: afbreken mag, tenzij dat door gerechtvaardigd vertrouwen of andere omstandigheden onaanvaardbaar is (Plas/Valburg, CBB/JPO). Hier: vier maanden onderhandelen, een letter of intent zonder voorbehoud, BouwBest liet kosten maken en zei 'het is rond'. BouwBest heeft dus sterk bijgedragen aan het vertrouwen. Een iets lagere prijs van een ander is een zwakke reden in deze afrondende fase. Waarschijnlijk is het afbreken onaanvaardbaar en dus onrechtmatig.",
     ["Uitgangspunt contractvrijheid en de uitzondering", "Minstens drie feiten uit de casus gewogen", "Onderbouwde conclusie"]),
    ("Welke schade kan FaciPro vorderen en op welke grondslag?",
     "Grondslag: onrechtmatige daad (art. 6:162 BW). Het negatief contractsbelang (de architect, €18.000, en andere gemaakte kosten) is standaard toewijsbaar. Het positief contractsbelang (de gederfde winst van €60.000) alleen bij uitzondering; hier is het verdedigbaar vanwege het vergevorderde stadium, de uitspraak 'het is rond' en de zwakke reden voor afbreken. Alternatief is een vordering tot dooronderhandelen, maar FaciPro moet dan snel een kort geding starten.",
     ["Grondslag 6:162 BW", "Negatief contractsbelang standaard", "Positief contractsbelang als uitzondering met argumenten"]),
    ("Hoe had FaciPro dit risico vooraf kunnen beperken, en hoe had BouwBest zich kunnen beschermen?",
     "FaciPro: afspraken over vergoeding van kosten (zoals de architect) in de letter of intent of een voorovereenkomst, en exclusiviteit voor een bepaalde periode. BouwBest: voorbehouden opnemen in de letter of intent (bijvoorbeeld pas gebonden na schriftelijke vastlegging en goedkeuring door de directie), zich daar ook aan houden, en geen uitspraken doen als 'het is rond'.",
     ["Maatregel voor FaciPro", "Voorbehouden voor BouwBest en zich eraan houden"])])
cs("ir5-rc2", W, R, "Battle of forms bij de levering van werkplekmeubilair",
   "Woningcorporatie Thuis (35 medewerkers) vraagt een offerte aan bij meubelfabrikant ErgoPro (220 medewerkers) en verwijst in de aanvraag naar haar eigen inkoopvoorwaarden. ErgoPro stuurt een offerte die verwijst naar haar leveringsvoorwaarden 'die op verzoek kosteloos worden toegezonden'. In die voorwaarden staat: 'Andere voorwaarden zijn uitgesloten' en 'Aansprakelijkheid van ErgoPro is beperkt tot €500.' Thuis accepteert de offerte. Later bezwijkt een stoel en raakt een medewerker gewond.",
   [("Welke algemene voorwaarden zijn van toepassing? Motiveer met het artikel.",
     "De inkoopvoorwaarden van Thuis. Volgens de first-shot rule (art. 6:225 lid 3 BW) geldt de eerste verwijzing. ErgoPro heeft die niet uitdrukkelijk van de hand gewezen: alleen naar de eigen voorwaarden verwijzen en een uitsluitingsclausule in de eigen voorwaarden zijn onvoldoende.",
     ["Voorwaarden van Thuis", "First-shot rule, art. 6:225 lid 3 BW", "Uitdrukkelijk van de hand wijzen ontbreekt"]),
    ("Stel dat toch de voorwaarden van ErgoPro gelden. Kan Thuis die vernietigen?",
     "Thuis heeft minder dan 50 medewerkers en is geen art. 6:235-onderneming, dus kan zij zich op art. 6:233 BW beroepen. Sub b (geen redelijke mogelijkheid tot kennisneming, art. 6:234): ErgoPro heeft de voorwaarden niet ter hand gesteld, terwijl dat wel kon; 'op verzoek toezenden' is onvoldoende, dus vernietigbaar. Daarnaast kan sub a (onredelijk bezwarend) worden aangevoerd voor de aansprakelijkheidsbeperking bij letselschade. De lijsten gelden niet, want Thuis is geen consument.",
     ["Thuis kan 6:233 gebruiken (geen 6:235-onderneming)", "Sub b met 6:234 toegepast", "Eventueel sub a, lijsten niet van toepassing"]),
    ("Beoordeel de aansprakelijkheidsbeperking tot €500 bij de gewonde medewerker, ook als ErgoPro een beroep op 6:248 lid 2 zou moeten weerleggen.",
     "Een exoneratie tot €500 bij letselschade is vaak onaanvaardbaar. Gezichtspunten: de aard van de schade (letsel weegt zwaarder dan zaakschade), ErgoPro als grote onderneming tegenover een kleinere wederpartij, verzekerbaarheid (ErgoPro kan productaansprakelijkheid verzekeren) en de mate van schuld. Een beroep op de clausule is daarom waarschijnlijk naar maatstaven van redelijkheid en billijkheid onaanvaardbaar (art. 6:248 lid 2 BW).",
     ["Toets via 6:248 lid 2", "Minstens twee gezichtspunten toegepast", "Conclusie"])])
